import express from 'express';
import crypto from 'crypto';

const app = express();

app.post('/webhooks/clickup', express.raw({ type: 'application/json' }), (req, res) => {
  const sig = req.headers['x-clickup-signature'] as string;
  const hash = crypto.createHmac('sha256', process.env.CLICKUP_SECRET!).update(req.body.toString('utf-8')).digest('hex');

